#include "stdafx.h"
#include "open_denoise.h"
#include "realtime_denoise.h"
#include "locked_frame.h"
#include <chrono>
#include <thread>
#include <atomic>
#include <cstdio>
static void Check(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
static void Hr(HRESULT hr){if(FAILED(hr))throw hr;}
static ComPtr<IMFMediaType> Type(UINT w,UINT h){ComPtr<IMFMediaType> type;Hr(MFCreateMediaType(&type));type->SetGUID(MF_MT_MAJOR_TYPE,MFMediaType_Video);type->SetGUID(MF_MT_SUBTYPE,MFVideoFormat_NV12);MFSetAttributeSize(type.Get(),MF_MT_FRAME_SIZE,w,h);type->SetUINT32(MF_MT_DEFAULT_STRIDE,w);return type;}
static ComPtr<IMFSample> Frame(UINT w,UINT h,bool edge=false){ComPtr<IMFSample> sample;ComPtr<IMFMediaBuffer> buffer;Hr(MFCreateSample(&sample));Hr(MFCreateMemoryBuffer(w*(h+h/2),&buffer));BYTE* data;Hr(buffer->Lock(&data,nullptr,nullptr));unsigned random=17;for(UINT y=0;y<h+h/2;y++)for(UINT x=0;x<w;x++){random=random*1664525+1013904223;int noise=int((random>>24)%49)-24;int value=y<h?(edge?(x<w/2?60:190):100):(x%2?170:90);data[y*w+x]=BYTE(value+noise);}buffer->Unlock();buffer->SetCurrentLength(w*(h+h/2));sample->AddBuffer(buffer.Get());sample->SetSampleTime(MFGetSystemTime());sample->SetSampleDuration(333333);sample->SetSampleFlags(1);sample->SetUINT32(MFSampleExtension_Discontinuity,TRUE);return sample;}
static double Mse(IMFSample* sample,IMFMediaType* type,UINT w,UINT h,bool edge){ComPtr<IMFMediaBuffer> buffer;Hr(sample->ConvertToContiguousBuffer(&buffer));Locked2D locked;Hr(locked.Lock(buffer.Get(),MF2DBuffer_LockFlags_Read,type));double error=0;for(UINT y=0;y<h;y++)for(UINT x=0;x<w;x++){double difference=locked.scan[y*locked.stride+x]-(edge?(x<w/2?60:190):100);error+=difference*difference;}return error/(w*h);}
static LONGLONG Timestamp(IMFSample* sample){LONGLONG time=0;Hr(sample->GetSampleTime(&time));return time;}
static double ChromaMse(IMFSample* sample,IMFMediaType* type,UINT w,UINT h){ComPtr<IMFMediaBuffer> buffer;Hr(sample->ConvertToContiguousBuffer(&buffer));Locked2D locked;Hr(locked.Lock(buffer.Get(),MF2DBuffer_LockFlags_Read,type));double error=0;for(UINT y=0;y<h/2;y++)for(UINT x=0;x<w;x++){double d=locked.scan[(h+y)*locked.stride+x]-(x%2?170:90);error+=d*d;}return error/(w*h/2);}
int main(){CoInitializeEx(nullptr,COINIT_MULTITHREADED);MFStartup(MF_VERSION);int result=0;try{
    auto type=Type(640,360);OpenGpuDenoiser denoiser;
    for(bool edge:{false,true}){auto frame=Frame(640,360,edge);auto original=frame;LONGLONG time=Timestamp(frame.Get());double before=Mse(frame.Get(),type.Get(),640,360,edge);Hr(denoiser.Process(type.Get(),frame.GetAddressOf(),4));double after=Mse(frame.Get(),type.Get(),640,360,edge);Check(after<before*.6,"GPU filter did not remove noise");Check(Mse(original.Get(),type.Get(),640,360,edge)==before,"GPU changed source buffer");Check(Timestamp(frame.Get())==time,"GPU retimestamped image");LONGLONG duration=0;frame->GetSampleDuration(&duration);Check(duration==333333,"duration lost");UINT32 discontinuity=0;frame->GetUINT32(MFSampleExtension_Discontinuity,&discontinuity);Check(discontinuity==TRUE,"metadata lost");std::printf("PASS: open-source D3D11 %s noise MSE %.2f -> %.2f; source, timestamp and metadata preserved.\n",edge?"edge":"flat",before,after);}
    auto large=Type(1920,1080);double total=0;for(int i=0;i<7;i++){auto frame=Frame(1920,1080);auto start=std::chrono::steady_clock::now();Hr(denoiser.Process(large.Get(),frame.GetAddressOf(),2));if(i>1)total+=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();}std::printf("PASS: warmed open GPU 1080p filter averages %.2f ms over five frames.\n",total/5);
    {auto frame=Frame(640,360);double before=ChromaMse(frame.Get(),type.Get(),640,360),lumaBefore=Mse(frame.Get(),type.Get(),640,360,false);Hr(denoiser.Process(type.Get(),frame.GetAddressOf(),4,true));double after=ChromaMse(frame.Get(),type.Get(),640,360);Check(after<before*.4,"colour cleanup did not suppress chroma noise");Check(Mse(frame.Get(),type.Get(),640,360,false)==lumaBefore,"colour cleanup changed luma detail");std::printf("PASS: targeted colour cleanup chroma MSE %.2f -> %.2f; luma pixels unchanged.\n",before,after);}
    {auto frame=Frame(640,360);auto original=frame.Get();Check(denoiser.Process(type.Get(),frame.GetAddressOf(),0)==S_FALSE&&frame.Get()==original,"Off changed image");type->SetGUID(MF_MT_SUBTYPE,MFVideoFormat_H264);Check(FAILED(denoiser.Process(type.Get(),frame.GetAddressOf(),1))&&frame.Get()==original,"unsupported format changed source");type->SetGUID(MF_MT_SUBTYPE,MFVideoFormat_NV12);}
    std::atomic<bool> entered=false,finished=false;RealtimeDenoiser realtime([&](IMFMediaType*,IMFSample**,DWORD,DWORD){if(!entered.exchange(true)){Sleep(700);finished=true;}return S_OK;});
    auto frame=Frame(640,360);auto start=std::chrono::steady_clock::now();Check(realtime.Process(type.Get(),frame.GetAddressOf(),1,0)==MF_E_TRANSFORM_NEED_MORE_INPUT&&!frame,"one frame headroom");Check(std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count()<40,"capture blocked on model start");
    while(!entered)std::this_thread::yield();LONGLONG previous=0;for(int i=0;i<8;i++){Sleep(10);auto next=Frame(640,360);Check(SUCCEEDED(realtime.Process(type.Get(),next.GetAddressOf(),1,0)),"warming output missing");auto time=Timestamp(next.Get());Check(time>previous,"timestamps repeated or reversed");previous=time;}
    auto off=Frame(640,360);auto original=off.Get();start=std::chrono::steady_clock::now();Check(realtime.Process(type.Get(),off.GetAddressOf(),0,0)==S_FALSE&&off.Get()==original,"Off did not return current input");Check(std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count()<40,"Off waited for model");Check(!finished,"cold-model test did not overlap Off");while(!finished)Sleep(10);Sleep(20);Check(realtime.Status().level==0&&realtime.Status().completed==0,"old GPU result leaked after Off");
    std::puts("PASS: simulated 700 ms RTX model startup never blocks capture; warming frames are monotonic; Off immediately uses fresh input and invalidates late results.");
}catch(const std::exception& error){std::fprintf(stderr,"FAIL: %s\n",error.what());result=1;}catch(HRESULT hr){std::fprintf(stderr,"FAIL: HRESULT 0x%08lx\n",hr);result=1;}MFShutdown();CoUninitialize();return result;}
